using System;
using System.Collections;
using System.Collections.Generic;
using System.IO;
using System.Linq;
using UnityEngine;
namespace Wildfolk.Editor
{
    // Explicit isolated fixture; positions use real terrain and RNG seeds select existing weighted outcomes.
    public static class FishingQa
    {
        public static string Phase{get;private set;}="idle";
        private static string Root=>Path.GetFullPath("Captures/fishing-aquatic-expansion");
        private static WorldSaveService s;private static PlayerInventory bag;private static NetworkSession host;private static NetworkPlayer actor;
        private static void Log(string text){Directory.CreateDirectory(Root);File.AppendAllText(Root+"/live.tsv",DateTime.UtcNow.ToString("O")+"\t"+Phase+"\t"+text+"\n");}
        private static void Check(bool ok,string text){Log((ok ? "PASS " : "FAIL ")+text);if(!ok)throw new InvalidOperationException(text);}
        private static void Step(string text){Phase=text;Log("begin");}
        private static IEnumerator Guard(IEnumerator flow)
        {var stack=new Stack<IEnumerator>();stack.Push(flow);while(stack.Count>0){bool more;object value;try{more=stack.Peek().MoveNext();value=more ? stack.Peek().Current : null;}catch(Exception e){Phase="failed";Log(e.ToString());yield break;}if(!more){stack.Pop();continue;}if(value is IEnumerator child)stack.Push(child);else yield return value;}Phase="complete";Log("complete");}
        private static IEnumerator Capture(string name)
        {if(Application.isBatchMode)yield break;yield return null;yield return new WaitForEndOfFrame();ScreenCapture.CaptureScreenshot(Root+"/"+name+".png");yield return new WaitForEndOfFrame();yield return null;}
        private static int Select(PlayerInventory b,ContentCatalog c,string id,bool give=true)
        {var item=c.Item(id);if(give && b.Model.CountItem(item)==0)b.Model.Add(item,1);var slot=Enumerable.Range(0,b.Model.Capacity).First(i=>b.Model.GetSlot(i).Item==item);if(slot>=9){var empty=Enumerable.Range(0,9).Where(i=>b.Model.GetSlot(i).IsEmpty).DefaultIfEmpty(b.SelectedIndex).First();b.Model.MoveStack(slot,empty);slot=empty;}b.SelectSlot(slot);return slot;}
        private static Vector2 Site(WorldMap map,FishingWater water)
        {
            if(water==FishingWater.Ocean){var lo=0f;var hi=map.Size.x*.5f;for(var i=0;i<30;i++){var mid=(lo+hi)*.5f;if(map.Continental.CoastDistance(new Vector2(mid,0))>1)lo=mid;else hi=mid;}return new Vector2(lo,0);}
            for(var y=517;y<3600;y+=17){var p=new Vector2(map.RiverAt(y)+7,y);if(FishingWaterContext.TryCast(map,p,Vector2.left,out var point) && FishingWaterContext.TrySample(map,point,false,out var context) && context.Water==water && context.Deep && context.ShoreInset>=2.25f)return p;}
            throw new InvalidOperationException("No actual shore site for "+water);
        }
        private static void Move(WorldGenerator world,PlayerInventory b,Vector2 p,Vector2 facing)
        {b.GetComponent<PlayerInputCommands>().Session.CloseInventory();var body=b.GetComponent<Rigidbody2D>();body.position=p;body.linearVelocity=Vector2.zero;b.transform.position=p;Physics2D.SyncTransforms();world.Chunks.Reconcile();world.Chunks.DrainPending();b.GetComponent<PlayerAvatar>().Facing.Face(facing);}
        private static void SeedFor(PlayerFishing fishing,WorldMap map,PlayerInventory b,bool night,string output)
        {Vector2 point;FishingWaterContext context;Check(FishingWaterContext.TryCast(map,b.transform.position,b.GetComponent<PlayerAvatar>().Facing.Direction,out point) && FishingWaterContext.TrySample(map,point,night,out context),"real water cast query");FishingWaterContext.TrySample(map,point,night,out context);for(var seed=0;seed<5000;seed++){UnityEngine.Random.InitState(seed);var index=fishing.CatchTable.Roll(context,UnityEngine.Random.value);if(index>=0 && fishing.CatchTable.Entries[index].Output.Id==output){UnityEngine.Random.InitState(seed);return;}}throw new InvalidOperationException("Catch not in actual table: "+output);}
        public static void Begin()
        {ContentExpansionQa.Prepare();s=ContentExpansionQa.S;bag=s.Player;s.World.Animals.enabled=s.World.Renewal.enabled=false;s.World.Animals.Restore(Array.Empty<AnimalSnapshot>(),new AnimalEcologySnapshot());Application.runInBackground=true;Phase="starting";s.StartCoroutine(Guard(Single()));}
        private static IEnumerator Catch(string id,FishingWater water,bool night)
        {
            Step("catch-"+id);var fishing=bag.GetComponent<PlayerFishing>();fishing.ResetTransient();Select(bag,s.Catalog,"fishing_rod",false);var p=Site(s.World.Map,water);var direction=water==FishingWater.Ocean ? Vector2.right : Vector2.left;Move(s.World,bag,p,direction);s.Clock.Model.SetElapsed(night ? 320 : 60);SeedFor(fishing,s.World.Map,bag,night,id);var before=bag.Model.CountItem(s.Catalog.Item(id));var t=Time.time;var catches=fishing.Catches;
            Check(bag.GetComponent<PlayerPrimaryAction>().TryUse(),"actual cast "+p+" to "+fishing.WaterPoint);Check(fishing.CatchTable.Entries[fishing.PendingCatch].Output.Id==id,"Host roll "+id+" water="+fishing.Context.Water+" inset="+fishing.Context.ShoreInset+" deep="+fishing.Context.Deep+" night="+fishing.Context.Night);Check(!fishing.Use(),"early reel rejected");yield return Capture(id+"-cast");yield return new WaitUntil(()=>fishing.Phase==FishingPhase.Bite);Log("measured cast-to-bite="+(Time.time-t));yield return Capture(id+"-bite");Check(fishing.Use(),"reel success");Check(!fishing.Use(),"same-frame duplicate rejected");Check(bag.Model.CountItem(s.Catalog.Item(id))==before+1 && fishing.Catches==catches+1,"exactly one inventory award");yield return null;yield return Capture(id+"-caught");yield return new WaitUntil(()=>fishing.Phase==FishingPhase.Idle);Log("measured full cycle="+(Time.time-t));
        }
        private static IEnumerator Cook(string id,CraftingStation station)
        {
            var r=s.Catalog.Recipe(id);foreach(var cost in r.Ingredients){var missing=cost.Count-bag.Model.CountItem(cost.Item);if(missing>0)bag.Model.Add(cost.Item,checked((int)missing));}var craft=bag.GetComponent<PlayerCrafting>();Check(craft.OpenStation(station),"open actual station "+id);craft.SetSelected(r);yield return null;var before=bag.Model.CountItem(r.Result);var card=UnityEngine.Object.FindFirstObjectByType<CraftingPanel>().Cards.Single(c=>c.Recipe==r);card.CraftButton.onClick.Invoke();Check(craft.Processor.IsBusy,"real recipe processing "+id);yield return Capture("cook-"+id);yield return new WaitForSeconds(r.ProcessingSeconds+.2f);Check(craft.Processor.Collect(bag),"take output "+id);Check(bag.Model.CountItem(r.Result)==before+r.ResultCount,"correct output count "+id);craft.CloseCrafting();
        }
        private static IEnumerator Single()
        {
            L.SetLanguage("ko");Step("rod-craft");ContentExpansionQa.Move(Vector2.zero);ContentExpansionQa.Clear(Vector2.zero,12);bag.Model.Restore(new InventoryModel(36).Capture(),s.Catalog);ContentExpansionQa.Bench=null;ContentExpansionQa.OpenBench();Check(ContentExpansionQa.Craft("fishing_rod")==1,"WBI Wood4+Fiber3 existing Rod crafted through card");bag.GetComponent<PlayerCrafting>().CloseCrafting();Select(bag,s.Catalog,"fishing_rod",false);var fishing=bag.GetComponent<PlayerFishing>();Move(s.World,bag,Vector2.zero,Vector2.right);Check(!fishing.Use(),"land cast rejected");
            yield return Catch("raw_fish",FishingWater.Inland,false);yield return Catch("crucian_carp",FishingWater.Wetlands,false);yield return Catch("perch",FishingWater.Inland,false);yield return Catch("mackerel",FishingWater.Ocean,false);L.SetLanguage("en");yield return Catch("eel",FishingWater.Wetlands,true);L.SetLanguage("ko");
            Step("cancel-fail-full");var p=Site(s.World.Map,FishingWater.Inland);Move(s.World,bag,p,Vector2.left);Check(fishing.Use(),"cast to expire");var old=fishing.Catches;yield return new WaitForSeconds(5.3f);Check(fishing.Phase==FishingPhase.Idle && fishing.Catches==old,"missed bite expires without reward");
            Check(fishing.Use(),"cast before move");bag.transform.position+=Vector3.up*2;yield return null;Check(fishing.Phase==FishingPhase.Idle,"movement cancels");Move(s.World,bag,p,Vector2.left);Check(fishing.Use(),"cast before tool switch");Select(bag,s.Catalog,"wood_spear");yield return null;Check(fishing.Phase==FishingPhase.Idle,"tool switch cancels");Select(bag,s.Catalog,"fishing_rod",false);Check(fishing.Use(),"cast before modal");s.World.Session.OpenInventory();yield return null;Check(fishing.Phase==FishingPhase.Idle,"inventory modal cancels");s.World.Session.CloseInventory();
            var empty=new InventoryModel(36);empty.Add(s.Catalog.Item("fishing_rod"),1);empty.Add(s.Catalog.Item("wood"),50*35);bag.Model.Restore(empty.Capture(),s.Catalog);bag.SelectSlot(0);Check(fishing.Use(),"full bag cast");var pending=fishing.PendingCatch;old=fishing.Catches;yield return new WaitUntil(()=>fishing.Phase==FishingPhase.Bite);Check(!fishing.Use() && fishing.Catches==old && fishing.PendingCatch==pending && fishing.Phase==FishingPhase.Bite,"full bag no reward or reroll");yield return Capture("bag-full");Check(bag.Model.ConsumeSlot(1,s.Catalog.Item("wood"),50),"free one slot");Check(fishing.Use() && fishing.Catches==old+1,"same pending catch succeeds once after free slot");yield return new WaitForSeconds(.7f);
            Step("processing-and-cooking");bag.Model.Restore(new InventoryModel(36).Capture(),s.Catalog);ContentExpansionQa.Move(Vector2.zero);ContentExpansionQa.Clear(Vector2.zero,14);var craft=bag.GetComponent<PlayerCrafting>();s.World.Session.OpenInventory();craft.OpenHandCrafting();
            foreach(var id in new[]{"crucian_carp","perch","mackerel","eel"}){bag.Model.Add(s.Catalog.Item(id),1);var r=s.Catalog.Recipe("fillet_"+id);var before=bag.Model.CountItem(r.Result);craft.SetSelected(r);yield return null;UnityEngine.Object.FindFirstObjectByType<CraftingPanel>().Cards.Single(c=>c.Recipe==r).CraftButton.onClick.Invoke();Check(bag.Model.CountItem(r.Result)==before+r.ResultCount,"actual Hand prepare "+id);yield return Capture("prepare-"+id);}
            craft.CloseCrafting();var fire=ContentExpansionQa.Place("campfire",new Vector2(2,0)).GetComponent<CraftingStation>();var pot=ContentExpansionQa.Place("cooking_pot",new Vector2(-2,0)).GetComponent<CraftingStation>();yield return Cook("fish_portions",fire);yield return Cook("cooked_fish",fire);yield return Cook("fish_stew",pot);yield return Cook("trail_broth",pot);
            bag.GetComponent<PlayerSurvival>().ResetTransient();bag.GetComponent<PlayerSurvival>().Model.SetMeters(20,20);Select(bag,s.Catalog,"fish_portions",false);var survival=bag.GetComponent<PlayerSurvival>();var hp=bag.GetComponent<Health>().Current;Check(bag.GetComponent<PlayerPrimaryAction>().TryUse() && !survival.Meal.Active && bag.GetComponent<Health>().Current==hp && survival.Model.Hunger>39,"portion nutrition only no Meal/heal");
            Step("save-load");foreach(var id in new[]{"crucian_carp","perch","mackerel","eel"})bag.Model.Add(s.Catalog.Item(id),2);Select(bag,s.Catalog,"fishing_rod");Move(s.World,bag,p,Vector2.left);Check(fishing.Use(),"pending cast before save");var beforeSave=bag.Model.Capture();Check(s.Save(),"isolated Save11");s.Apply(s.Repository.Read(s.Validate));yield return null;Check(fishing.Phase==FishingPhase.Idle && fishing.PendingCatch<0,"Load discards transient fishing");Check(JsonUtility.ToJson(new StackWrapper{Stacks=bag.Model.Capture()})==JsonUtility.ToJson(new StackWrapper{Stacks=beforeSave}),"new and existing item stacks exactly restored");yield return Capture("loaded");
            Check(fishing.Use(),"new cast after Load");bag.GetComponent<PlayerClass>()?.RestoreCooldown(360);bag.GetComponent<Health>().ApplyDamage(10000,true);yield return null;Check(fishing.Phase==FishingPhase.Idle,"death cancels fishing");
        }
        [Serializable]private sealed class StackWrapper{public SavedStack[] Stacks;}
        public static void BeginHost()
        {if(!DevelopmentProfile.Isolated)throw new InvalidOperationException("Isolated QA required");UnityEngine.Object.FindFirstObjectByType<HomeScreen>().OpenMultiplayer();host=NetworkSession.Instance;host.WorldRepository=new SaveRepository(Root+"/host/"+Guid.NewGuid().ToString("N")+"/world.json");host.ProfileOverride=Guid.NewGuid().ToString("N");host.NewWorldGenerationVersion=3;Application.runInBackground=true;Phase="starting";host.StartCoroutine(Guard(HostFlow()));}
        private static IEnumerator EnterHost()
        {var task=host.Host(ConnectionRoute.LocalNetwork);yield return new WaitUntil(()=>task.IsCompleted);Check(task.Result,"Local Host "+host.LastFailure);Check(host.EnterGame(),"enter Host world");var until=Time.realtimeSinceStartup+45;while(Time.realtimeSinceStartup<until){actor=NetworkPlayer.Active.FirstOrDefault(p=>p.IsSpawned && p.NetworkObject.IsPlayerObject);if(actor!=null && NetworkCreatureWorld.Active!=null && NetworkCreatureWorld.Active.Ready)break;yield return null;}Check(actor!=null && NetworkCreatureWorld.Active.Ready,"Host world ready");actor.Motor.enabled=actor.GetComponent<PlayerInputAdapter>().enabled=false;var w=NetworkCreatureWorld.Active;w.Clock.enabled=w.Animals.enabled=w.Goblins.enabled=w.Night.enabled=w.World.Renewal.enabled=false;yield return null;}
        private static IEnumerator HostFlow()
        {
            Step("host-catch");yield return EnterHost();var w=NetworkCreatureWorld.Active;var c=w.Catalog;bag=actor.GetComponent<PlayerInventory>();bag.Model.Restore(new InventoryModel(36).Capture(),c);Select(bag,c,"fishing_rod");var p=Site(w.World.Map,FishingWater.Wetlands);Move(w.World,bag,p,Vector2.left);w.Clock.Model.SetElapsed(320);var fishing=bag.GetComponent<PlayerFishing>();SeedFor(fishing,w.World.Map,bag,true,"eel");Check(actor.ExecutePrimary(1),"Host cast request accepted");Check(!actor.ExecutePrimary(1),"duplicate cast request rejected");yield return new WaitUntil(()=>fishing.Phase==FishingPhase.Bite);Check(actor.ExecutePrimary(2),"Host reel request accepted");Check(!actor.ExecutePrimary(2) && !actor.ExecutePrimary(3),"duplicate and newer recovery requests rejected");Check(bag.Model.CountItem(c.Item("eel"))==1,"Host one eel award");var activity=actor.GetComponent<NetworkActivities>().Activity.Value;Check(activity.Kind==ActivityKind.FishingCaught && fishing.CatchTable.Entries[activity.CatchIndex].Output.Id=="eel" && activity.CatchCount==1,"replicated catch index/count from server");yield return Capture("host-caught");yield return new WaitForSeconds(.7f);
            Check(actor.ExecutePrimary(4),"pending Host cast before Save");Check(host.TrySaveWorld(),"Host Save11 while waiting");host.Leave();yield return new WaitUntil(()=>host.State==NetworkSessionState.Idle);yield return new WaitForSecondsRealtime(.3f);Step("rehost");yield return EnterHost();bag=actor.GetComponent<PlayerInventory>();fishing=bag.GetComponent<PlayerFishing>();Check(fishing.Phase==FishingPhase.Idle && bag.Model.CountItem(c.Item("eel"))==1,"reHost exact catch inventory and no pending reward");Check(bag.SelectedStack.Item.Id=="fishing_rod","selected Rod restored");Check(actor.GetComponent<NetworkActivities>().Activity.Value.Kind==ActivityKind.None,"reHost activity Idle");yield return Capture("rehost");
        }
    }
}
